import React, { useState, useEffect } from 'react';
import { Smartphone, Users, MonitorSmartphone, Monitor, Globe, ShieldCheck, Zap, Activity, CheckCircle2, XCircle, ChevronDown, Bluetooth, Bot, Lock, Server } from 'lucide-react';

interface LandingPageProps {
  onLogin?: () => void;
  onRegisterOrg?: () => void;
  onRegisterUser?: () => void;
  onBackToApp?: () => void;
  isLoggedIn?: boolean;
}

export function LandingPage({ onLogin, onRegisterUser, onBackToApp, isLoggedIn }: LandingPageProps) {
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [activeZone, setActiveZone] = useState<string | null>(null);
  const [tourStep, setTourStep] = useState<number | null>(null);
  const [isScrolled, setIsScrolled] = useState(false);
  const [demoMode, setDemoMode] = useState(false);

  useEffect(() => {
    const handleScroll = () => setIsScrolled(window.scrollY > 10);
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  // Handle Tour Mode
  useEffect(() => {
    let interval: ReturnType<typeof setInterval>;
    if (tourStep !== null) {
      interval = setInterval(() => {
        setTourStep((prev) => {
          if (prev === null) return 0;
          const next = prev + 1;
          if (next > 3) {
            clearInterval(interval);
            return null;
          }
          return next;
        });
      }, 3000);
    }
    return () => {
      if (interval) clearInterval(interval);
    };
  }, [tourStep]);

  useEffect(() => {
    if (tourStep !== null) {
      setActiveZone(`zone${tourStep + 1}`);
      if (tourStep === 0) {
        document.getElementById('technology')?.scrollIntoView({ behavior: 'smooth', block: 'center' });
      }
    }
  }, [tourStep]);

  const toggleZone = (id: string) => {
    setTourStep(null);
    setActiveZone(activeZone === id ? null : id);
  };

  const handleRequestDemo = (e: React.MouseEvent) => {
    // keeping WhatsApp redirect unless strictly internal
  };

  return (
    <div className="bg-white min-h-screen font-sans text-slate-800 antialiased overflow-x-hidden">
      <style dangerouslySetInnerHTML={{ __html: `
        @keyframes ping-custom { 0% { transform: scale(1); opacity: 1; } 75%, 100% { transform: scale(2.5); opacity: 0; } }
        .pulse-ring::before { content: ''; position: absolute; inset: 0; border-radius: 50%; animation: ping-custom 1.5s cubic-bezier(0, 0, 0.2, 1) infinite; }
        .pulse-green::before { background: rgba(34, 197, 94, 0.6); }
        .pulse-blue::before { background: rgba(59, 130, 246, 0.6); }
        .pulse-amber::before { background: rgba(245, 158, 11, 0.6); }
        .pulse-red::before { background: rgba(239, 68, 68, 0.6); }

        @keyframes expand { 0% { transform: translate(-50%, -50%) scale(0.5); opacity: 0.8; } 100% { transform: translate(-50%, -50%) scale(3); opacity: 0; } }
        .dispatch-ring { position: absolute; left: 50%; top: 50%; width: 60px; height: 60px; border: 2px solid rgba(21, 128, 61, 0.6); border-radius: 50%; animation: expand 2.5s ease-out infinite; }
        .dispatch-ring:nth-child(2) { animation-delay: 0.8s; }
        .dispatch-ring:nth-child(3) { animation-delay: 1.6s; }

        .zone-panel { position: absolute; bottom: 0; left: 0; right: 0; background: rgba(15, 23, 42, 0.92); backdrop-filter: blur(12px); border-top: 1px solid rgba(21, 128, 61, 0.4); padding: 16px; transform: translateY(100%); transition: transform 0.35s cubic-bezier(0.4, 0, 0.2, 1); z-index: 20; border-radius: 0 0 12px 12px; }
        .zone-panel.open { transform: translateY(0); }
        .zone-card { position: relative; border-radius: 12px; overflow: hidden; cursor: pointer; border: 1px solid transparent; }
        @media (hover: hover) { .zone-card:hover .zone-panel { transform: translateY(0); } }
        .zone-card.active .zone-panel { transform: translateY(0); }
        .zone-card.tour-active { box-shadow: 0 0 0 2px #15803d, inset 0 0 24px rgba(21, 128, 61, 0.2); }
      `}} />

      {/* ══ NAVBAR ══════════════════════════════════════════════════════════ */}
      <nav id="navbar" className={`fixed top-0 left-0 right-0 z-50 bg-white transition-shadow duration-300 ${isScrolled ? 'shadow-md' : ''}`}>
        <div className="max-w-7xl mx-auto px-6 h-[72px] flex items-center justify-between">
          <a href="#" className="flex items-center gap-3 no-underline">
            <svg width="32" height="32" viewBox="0 0 36 36" fill="none">
              <path d="M18 3L5 8.5v9C5 24.8 10.8 30.7 18 33c7.2-2.3 13-8.2 13-15.5v-9L18 3z" fill="#f0fdf4" stroke="#15803d" strokeWidth="2"/>
              <path d="M13 18c0-2.8 2.2-5 5-5s5 2.2 5 5" stroke="#15803d" strokeWidth="2.5" strokeLinecap="round"/>
              <path d="M18 13v10M15 16l3-3 3 3" stroke="#15803d" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"/>
            </svg>
            <span className="text-[22px] font-bold text-[#0f172a] tracking-tight">SafetyLink</span>
          </a>

          <div className="hidden lg:flex gap-8 items-center">
            <a href="#home" className="text-sm font-semibold text-[#15803d] border-b-2 border-[#15803d] pb-1">Home</a>
            <a href="#platform" className="text-sm font-medium text-slate-600 hover:text-[#15803d] transition-colors">Platform</a>
            <a href="#use-cases" className="text-sm font-medium text-slate-600 hover:text-[#15803d] transition-colors">Use Cases</a>
            <a href="#hardware" className="text-sm font-medium text-slate-600 hover:text-[#15803d] transition-colors">Hardware</a>
            <a href="#pricing" className="text-sm font-medium text-slate-600 hover:text-[#15803d] transition-colors">Pricing</a>

            <button onClick={onLogin} className="text-sm font-bold text-[#0f172a] hover:text-[#15803d] transition-colors ml-2">Login</button>
            <a href="https://wa.me/27739441222?text=Hi+I+want+to+request+a+SafetyLink+demo" target="_blank" rel="noreferrer" className="bg-[#15803d] hover:bg-green-700 text-white px-6 py-2.5 rounded-full text-sm font-bold transition-colors shadow-sm">Request Demo</a>
          </div>

          <button onClick={() => setMobileMenuOpen(!mobileMenuOpen)} className="lg:hidden p-2 text-slate-800">
            <svg width="24" height="24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
              {mobileMenuOpen ? <><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></> : <><line x1="3" y1="6" x2="21" y2="6"/><line x1="3" y1="12" x2="21" y2="12"/><line x1="3" y1="18" x2="21" y2="18"/></>}
            </svg>
          </button>
        </div>

        {mobileMenuOpen && (
          <div className="lg:hidden bg-white border-t border-slate-200 px-6 py-4 flex flex-col gap-4 shadow-lg absolute w-full left-0">
            <a href="#home" onClick={() => setMobileMenuOpen(false)} className="text-[#15803d] font-semibold text-[15px]">Home</a>
            <a href="#platform" onClick={() => setMobileMenuOpen(false)} className="text-slate-600 font-medium text-[15px]">Platform</a>
            <a href="#use-cases" onClick={() => setMobileMenuOpen(false)} className="text-slate-600 font-medium text-[15px]">Use Cases</a>
            <a href="#hardware" onClick={() => setMobileMenuOpen(false)} className="text-slate-600 font-medium text-[15px]">Hardware</a>
            <a href="#pricing" onClick={() => setMobileMenuOpen(false)} className="text-slate-600 font-medium text-[15px]">Pricing</a>
            <button onClick={() => { setMobileMenuOpen(false); if(onLogin) onLogin(); }} className="text-slate-600 font-medium text-[15px] text-left">Login</button>
            <a href="https://wa.me/27739441222" target="_blank" rel="noreferrer" className="bg-[#15803d] text-white p-3 rounded-full font-bold text-center text-[15px] block">Request Demo</a>
          </div>
        )}
      </nav>

